#!/usr/bin/env node
// Extend the stack's existing llms.txt convention. No new agent protocol.
// --check validates generated files and Caddy inventory without writing.
// --probe verifies public HTTPS text, discovery headers and curated links.
import {readFile, writeFile, mkdir} from "node:fs/promises";
import {properties, excludedHosts} from "./machine-properties.mjs";
const root = new URL("../", import.meta.url);
const check = process.argv.includes("--check");
const probe = process.argv.includes("--probe");
const publicRoot = new URL("system/public/", root);
const caddyFile = new URL("lith/Caddyfile", root);
const hostMap = new Map();
for (const p of properties) {
  if (!/^[a-z0-9.-]+$/.test(p.host)) throw new Error(`Invalid hostname ${p.host}`);
  for (const host of [p.host, ...(p.aliases || [])]) {
    if (hostMap.has(host)) throw new Error(`Duplicate host ${host}`);
    hostMap.set(host, p);
  }
  for (const [, url] of p.links) {
    if (new URL(url).protocol !== "https:") throw new Error(`Non-HTTPS resource ${url}`);
  }
}
const link = ([name, url, description]) => `- [${name}](${url}): ${description}`;
const hosts = [...hostMap.keys()].sort();
const start = "# generated:machine-discovery:start";
const end = "# generated:machine-discovery:end";
const snippet = `${start}
# Generated by utilities/generate-machine-manifests.mjs. Exact public hosts
# only: unknown hosts, client sites, robots rules and API auth are untouched.
(machine_discovery) {
    map {host} {machine_readme_file} {
        default ""
${hosts.map(h => `        ~(?i)^${h.replaceAll(".", "[.]")}$ ${hostMap.get(h).file || `machine/${hostMap.get(h).host}.txt`}`).join("\n")}
    }
    @machine_host host ${hosts.join(" ")}
    header @machine_host +Link "</llms.txt>; rel=\\"describedby\\"; type=\\"text/plain\\""
    @machine_readme {
        host ${hosts.join(" ")}
        path /llms.txt
    }
    handle @machine_readme {
        root * /opt/ac/system/public
        rewrite * /{machine_readme_file}
        header Content-Type "text/plain; charset=utf-8"
        header Cache-Control "public, max-age=300"
        file_server
    }
}
${end}`;

let failed = false;
async function output(relative, content) {
  const file = new URL(relative, root);
  let current;
  try {current = await readFile(file, "utf8");} catch (e) {if (e.code !== "ENOENT") throw e;}
  if (content === current) return;
  if (check) {console.error(`Out of date: ${relative}`); failed = true;}
  else {await mkdir(new URL("./", file), {recursive: true}); await writeFile(file, content);}
}

if (probe) {
  // One bounded GET per unique resource; no POSTs, cookies or authentication.
  const targets = new Map();
  for (const host of hosts) targets.set(`https://${host}/llms.txt`, {text: true, header: true});
  for (const p of properties) for (const [,url] of p.links) if (!targets.has(url)) targets.set(url, {});
  const rows = [...targets];
  let errors = 0;
  for (let i = 0; i < rows.length; i += 6) {
    await Promise.all(rows.slice(i, i + 6).map(async ([url, expected]) => {
      try {
        const r = await fetch(url, {signal: AbortSignal.timeout(15000), headers: {"User-Agent": "AC-Machine-Discovery-Check/1.0"}});
        const type = r.headers.get("content-type") || "";
        // /mcp is SSE; SPARQL rejects a missing query. These are discovery
        // endpoints, so check their documented protocol response separately.
        const allowed = url.endsWith("/sparql") ? [200, 400, 405] : [200];
        let valid = allowed.includes(r.status);
        let body = "";
        if (expected.text || /\.json(?:\?|$)|[?&]format=json/.test(url)) body = await r.text();
        else await r.body?.cancel();
        if (expected.text) valid &&= /text\/(plain|markdown)/i.test(type) && /^#\s+\S/m.test(body) && !/<(?:!doctype|html)/i.test(body);
        if (expected.header) valid &&= /<\/llms\.txt>; rel="describedby"/.test(r.headers.get("link") || "");
        if (/\.json(?:\?|$)|[?&]format=json/.test(url)) {
          try {JSON.parse(body);} catch {valid = false;}
        }
        console.log(JSON.stringify({url, status: r.status, type, valid, final: r.url}));
        if (!valid) errors++;
      } catch (e) {errors++; console.log(JSON.stringify({url, valid: false, error: e.message, cause: e.cause?.code}));}
    }));
  }
  console.error(`${rows.length} public resources checked; ${errors} failures`);
  process.exitCode = errors ? 1 : 0;
} else {
  let caddy = await readFile(caddyFile, "utf8");
  const withoutGenerated = caddy.replace(new RegExp(`${start}[\\s\\S]*?${end}\\n*`), "");
  // Parse explicit Caddy host tokens, not arbitrary URLs in comments.
  const caddyHosts = new Set();
  for (const line of withoutGenerated.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    if (/\bhost\s/.test(trimmed) || (!/^\s/.test(line) && trimmed.endsWith("{"))) {
      for (const host of trimmed.match(/[a-z0-9-]+(?:\.[a-z0-9-]+)+/g) || []) caddyHosts.add(host);
    }
  }
  const unknown = [...caddyHosts].filter(h => !hostMap.has(h) && !excludedHosts[h]);
  if (unknown.length) throw new Error(`Classify new Caddy hosts in machine-properties.mjs: ${unknown.join(", ")}`);
  caddy = caddy.includes(start) ? caddy.replace(new RegExp(`${start}[\\s\\S]*?${end}`), snippet) : `${snippet}\n\n${caddy}`;
  await output("lith/Caddyfile", caddy);
  for (const p of properties) {
    if (p.file) {await readFile(new URL(p.file, publicRoot)); continue;}
    const content = `# ${p.title}\n\n> ${p.summary}\n\n${p.note ? p.note + "\n\n" : ""}## Resources\n\n${p.links.map(link).join("\n")}\n\n## Network\n\n- [Aesthetic Computer machine directory](https://aesthetic.computer/network.json): Public properties, descriptions and machine entry points.\n`;
    await output(`system/public/machine/${p.host}.txt`, content);
  }
  const directory = {title: "Aesthetic Computer public machine directory", version: 1,
    description: "Curated public products served by this stack. This is a link directory, not an agent protocol or an authorization grant. See each resource's own terms, authentication and attribution.",
    properties: properties.map(({host,title,summary,aliases=[],links,note}) => ({url:`https://${host}/`, title, summary, llms:`https://${host}/llms.txt`, aliases, ...(note ? {note} : {}), resources: links.map(([title,url,description]) => ({title,url,description}))}))};
  await output("system/public/network.json", JSON.stringify(directory, null, 2) + "\n");
  // Repair robots.txt's already-advertised, previously missing sitemap.xml.
  // Only canonical AC-host public discovery resources belong in this sitemap.
  const xmlURLs = ["/", "/about", "/list", "/docs", "/api", "/llms.txt", "/llms-full.txt", "/network.json"];
  await output("system/public/sitemap.xml", `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${xmlURLs.map(p=>`  <url><loc>https://aesthetic.computer${p}</loc></url>`).join("\n")}\n</urlset>\n`);
  console.log(`${properties.length} properties, ${hosts.length} hostnames; ${check ? "checked" : "generated"}. ${Object.keys(excludedHosts).length} hosts explicitly excluded.`);
  process.exitCode = failed ? 1 : 0;
}
